const DEFAULT_COLORS = [
  '#ff4d6d',
  '#ffb703',
  '#2ec4b6',
  '#7b61ff',
  '#00a8e8',
  '#ff8a00',
  '#8bc34a',
  '#e84a9a',
]

function ensureShadow() {
  if (typeof document === 'undefined') return null
  const host = document.createElement('div')
  host.dataset.cursorReplay = ''
  host.setAttribute('aria-hidden', 'true')
  const shadow = host.attachShadow({ mode: 'open' })
  const style = document.createElement('style')
  style.textContent = STYLE_TEXT
  shadow.appendChild(style)
  return { host, shadow }
}

function parseColor(value: string) {
  const match = value.match(/rgba?\(([^)]+)\)/i)
  if (!match) return null
  const parts = match[1].split(/[,\s/]+/).filter(Boolean)
  const r = Number(parts[0])
  const g = Number(parts[1])
  const b = Number(parts[2])
  const a = parts[3] === undefined ? 1 : parts[3].endsWith('%') ? Number(parts[3].slice(0, -1)) / 100 : Number(parts[3])
  if ([r, g, b, a].some((n) => !Number.isFinite(n))) return null
  return { r, g, b, a }
}

function textRanges(element: HTMLElement) {
  const ranges: Array<{ text: string; rect: DOMRect }> = []
  for (const node of Array.from(element.childNodes)) {
    if (node.nodeType !== Node.TEXT_NODE) continue
    const text = (node.textContent ?? '').replace(/\s+/g, ' ').trim()
    if (!text) continue
    const range = document.createRange()
    range.selectNodeContents(node)
    const rect = range.getBoundingClientRect()
    if (rect.width < 4 || rect.height < 4) continue
    ranges.push({ text: text.slice(0, 120), rect })
  }
  if (ranges.length === 0 && element.childElementCount === 0) {
    const text = (element.textContent ?? '').replace(/\s+/g, ' ').trim()
    const rect = element.getBoundingClientRect()
    if (text && rect.width >= 4 && rect.height >= 4) {
      ranges.push({ text: text.slice(0, 120), rect })
    }
  }
  return ranges
}

function elementRect(element: Element) {
  const rect = element.getBoundingClientRect()
  return rect.width >= 8 && rect.height >= 6 ? rect : null
}

export function collectTargets(
  root: HTMLElement,
  maxTargets = 80,
  fullscreen = root === document.body,
): ReplayTarget[] {
  if (typeof window === 'undefined') return []
  const viewport = {
    left: 0,
    top: 0,
    right: window.innerWidth,
    bottom: window.innerHeight,
  }
  const rootRect = fullscreen ? viewport : root.getBoundingClientRect()
  if (rootRect.right - rootRect.left < 20 || rootRect.bottom - rootRect.top < 20) return []

  const layers: ReplayTarget[] = []
  const nodes = Array.from(root.querySelectorAll<HTMLElement>('*'))
  for (const element of nodes) {
    if (element.closest('[data-cursor-replay]')) continue
    const tag = element.tagName.toLowerCase()
    if (['script', 'style', 'noscript', 'template', 'head', 'meta', 'link', 'br'].includes(tag)) {
      continue
    }
    const style = window.getComputedStyle(element)
    if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') {
      continue
    }
    const rect = elementRect(element)
    if (!rect) continue
    if (
      rect.width >= (rootRect.right - rootRect.left) * 0.96 &&
      rect.height >= (rootRect.bottom - rootRect.top) * 0.96
    ) {
      // Skip full-page layout wrappers; otherwise their background paints over
      // every box drawn underneath them.
      continue
    }
    if (
      rect.right < viewport.left - 20 ||
      rect.bottom < viewport.top - 20 ||
      rect.left > rootRect.right + 20 ||
      rect.top > rootRect.bottom + 20
    ) {
      continue
    }
    const x = rect.left - rootRect.left
    const y = rect.top - rootRect.top
    if (x < -8 || y < -8 || x > rootRect.right - rootRect.left || y > rootRect.bottom - rootRect.top) {
      continue
    }

    const alpha = parseColor(style.backgroundColor)?.a ?? 0
    const hasBorder =
      parseFloat(style.borderTopWidth) > 0 ||
      parseFloat(style.borderRightWidth) > 0 ||
      parseFloat(style.borderBottomWidth) > 0 ||
      parseFloat(style.borderLeftWidth) > 0
    const hasShadow = style.boxShadow !== 'none'
    const texts = textRanges(element)
    const tagIsMedia = tag === 'img' || tag === 'svg'
    const tagIsVisual = tagIsMedia || tag === 'button' || tag === 'input'
    if (alpha < 0.04 && !hasBorder && !hasShadow && texts.length === 0 && !tagIsVisual) continue

    if (alpha >= 0.04 || hasBorder || hasShadow) {
      const border = hasBorder
        ? `${style.borderTopWidth} ${style.borderTopStyle} ${style.borderTopColor}`
        : undefined
      layers.push({
        kind: 'rect',
        x,
        y,
        width: rect.width,
        height: rect.height,
        fill: alpha >= 0.04 ? style.backgroundColor : 'transparent',
        border,
        radius: style.borderRadius === '0px' ? undefined : style.borderRadius,
      })
    }

    for (const range of texts) {
      layers.push({
        kind: 'text',
        x: range.rect.left - rootRect.left,
        y: range.rect.top - rootRect.top,
        width: range.rect.width,
        height: range.rect.height,
        text: range.text,
        font: style.fontFamily,
        fontSize: parseFloat(style.fontSize) || 16,
        fontWeight: style.fontWeight,
        lineHeight: style.lineHeight === 'normal' ? undefined : style.lineHeight,
        letterSpacing: style.letterSpacing === 'normal' ? undefined : style.letterSpacing,
        textAlign: style.textAlign,
        color: style.color,
      })
    }

    if (tag === 'img') {
      const image = element as HTMLImageElement
      layers.push({
        kind: 'image',
        x,
        y,
        width: rect.width,
        height: rect.height,
        src: image.currentSrc || image.src,
        radius: style.borderRadius === '0px' ? undefined : style.borderRadius,
      })
    } else if (tag === 'svg') {
      layers.push({
        kind: 'image',
        x,
        y,
        width: rect.width,
        height: rect.height,
        svg: element.outerHTML,
      })
    }
  }

  const priority = (layer: ReplayTarget) =>
    (layer.kind === 'image' ? 3 : layer.kind === 'text' ? 2 : 1) * 100000 +
    layer.width * layer.height

  return layers
    .sort((a, b) => priority(b) - priority(a))
    .slice(0, clamp(maxTargets, 8, 240))
    .sort((a, b) => a.y - b.y || a.x - b.x)
}

function cursorSvg(shape: string) {
  if (shape === 'cross') {
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3V21M3 12H21" stroke="#fffdf8" stroke-width="4" stroke-linecap="round"/><path d="M12 3V21M3 12H21" stroke="var(--cr-color)" stroke-width="2" stroke-linecap="round"/></svg>'
  }
  if (shape === 'ibeam') {
    return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 4H10.5Q12 4 12 5.5Q12 4 13.5 4H16M12 5.5V18.5M8 20H10.5Q12 20 12 18.5Q12 20 13.5 20H16" fill="none" stroke="#fffdf8" stroke-width="3.4" stroke-linecap="round"/><path d="M8 4H10.5Q12 4 12 5.5Q12 4 13.5 4H16M12 5.5V18.5M8 20H10.5Q12 20 12 18.5Q12 20 13.5 20H16" fill="none" stroke="var(--cr-color)" stroke-width="1.5" stroke-linecap="round"/></svg>'
  }
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 2.5L20 11L11.5 12.4L14.5 21L10.7 22.2L7.8 13.5L4 16.5Z" fill="var(--cr-color)" stroke="#fffdf8" stroke-width="1.4" stroke-linejoin="round"/></svg>'
}

function cursorShapeFor(layer: ReplayTarget) {
  return layer.kind === 'text' ? 'ibeam' : layer.kind === 'rect' || layer.kind === 'image' ? 'cross' : 'arrow'
}

export function createCursorReplay(
  root: HTMLElement = document.body,
  options: ReplayOptions = {},
): ReplayController {
  const fullscreen = options.fullscreen ?? root === document.body
  const anchored = fullscreen && (options.anchor ?? 'fixed') === 'viewport'
  const duration = clamp(options.duration ?? 6500, 1800, 20000)
  const cursorCount = clamp(Math.floor(options.cursors ?? 6), 2, 10)
  const colors = options.colors?.length ? options.colors : DEFAULT_COLORS
  const ink = options.ink ?? '#1c1917'
  const surface = options.surface ?? '#fffaf0'
  const reduced = options.reducedMotion ?? 'auto'

  let shadowHost: { host: HTMLDivElement; shadow: ShadowRoot } | null = null
  let overlay: HTMLDivElement | null = null
  let frame = 0
  let playing = false
  let destroyed = false
  let resolvePlay: (() => void) | null = null
  let currentPlay: Promise<void> | null = null
  let previousPosition = ''
  let changedPosition = false
  let previousOverflow = ''
  let previousPointerEvents = ''
  let lockedOverflow = false
  let tasks: Task[] = []
  let layerEls: HTMLElement[] = []
  let cursorEls: HTMLDivElement[] = []
  let badgeEls: HTMLDivElement[] = []
  let endAt = 0
  let introEnd = 0
  let center = { x: 0, y: 0 }
  let onKey: ((event: KeyboardEvent) => void) | null = null

  const cleanup = () => {
    if (frame) cancelAnimationFrame(frame)
    frame = 0
    if (onKey) window.removeEventListener('keydown', onKey, true)
    onKey = null
    shadowHost?.host.remove()
    shadowHost = null
    overlay = null
    layerEls = []
    cursorEls = []
    badgeEls = []
    tasks = []
    if (lockedOverflow) {
      document.documentElement.style.overflow = previousOverflow
      document.body.style.pointerEvents = previousPointerEvents
      lockedOverflow = false
    }
    if (changedPosition) {
      root.style.position = previousPosition
      changedPosition = false
    }
    playing = false
  }

  const finish = () => {
    cleanup()
    const resolve = resolvePlay
    resolvePlay = null
    currentPlay = null
    try {
      options.onComplete?.()
    } finally {
      resolve?.()
    }
  }

  const cancel = () => {
    if (!playing) return
    cancelAnimationFrame(frame)
    frame = 0
    cleanup()
    const resolve = resolvePlay
    resolvePlay = null
    currentPlay = null
    resolve?.()
  }

  const play = () => {
    if (destroyed) return Promise.resolve()
    if (currentPlay) return currentPlay
    if (reduced !== 'play' && (reduced === 'skip' || prefersReducedMotion())) {
      return Promise.resolve()
    }
    const layers = collectTargets(root, options.maxTargets, fullscreen)
    if (layers.length === 0) return Promise.resolve()

    if (!fullscreen) {
      const position = window.getComputedStyle(root).position
      if (position === 'static') {
        previousPosition = root.style.position
        root.style.position = 'relative'
        changedPosition = true
      }
    }
    if (fullscreen && options.lockScroll) {
      previousOverflow = document.documentElement.style.overflow
      previousPointerEvents = document.body.style.pointerEvents
      document.documentElement.style.overflow = 'hidden'
      document.body.style.pointerEvents = 'none'
      lockedOverflow = true
    }

    shadowHost = ensureShadow()
    if (!shadowHost) return Promise.resolve()
    overlay = document.createElement('div')
    overlay.className = `replay-root${fullscreen ? (anchored ? ' anchored' : ' fixed') : ''}`
    if (anchored) {
      overlay.style.top = `${window.scrollY}px`
      overlay.style.left = '0'
      overlay.style.width = '100vw'
      overlay.style.height = '100vh'
    }
    overlay.style.setProperty('--cr-surface', surface)
    overlay.style.setProperty('--cr-ink', ink)
    shadowHost.shadow.appendChild(overlay)
    if (fullscreen) {
      document.body.appendChild(shadowHost.host)
    } else {
      root.appendChild(shadowHost.host)
    }

    const rootRect = fullscreen
      ? { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight }
      : root.getBoundingClientRect()
    center = { x: rootRect.width / 2, y: rootRect.height / 2 }

    // Large content first: the hero heading and image appear in the opening
    // beat instead of spending the intro on tiny header icons.
    const ordered = [...layers].sort(
      (a, b) => b.width * b.height - a.width * a.height,
    )
    layerEls = ordered.map((layer, index) => {
      const element = document.createElement('div')
      element.className = `replay-layer ${layer.kind}`
      element.style.left = `${layer.x}px`
      element.style.top = `${layer.y}px`
      element.style.width = `${layer.width}px`
      element.style.height = `${layer.height}px`
      element.style.setProperty('--cr-color', colors[index % colors.length])
      if (layer.radius) element.style.borderRadius = layer.radius
      if (layer.kind === 'rect') {
        element.style.setProperty('--cr-fill', layer.fill ?? 'transparent')
        if (layer.border) element.style.border = layer.border
        element.style.outline = `1.5px solid ${colors[index % colors.length]}`
        element.style.outlineOffset = '0'
        element.style.clipPath = 'inset(0 100% 100% 0)'
      } else if (layer.kind === 'image') {
        if (layer.svg) {
          element.innerHTML = layer.svg
        } else if (layer.src) {
          const image = document.createElement('img')
          image.src = layer.src
          image.alt = ''
          image.loading = 'eager'
          element.appendChild(image)
        }
        element.style.opacity = '0'
      } else {
        element.textContent = layer.text ?? ''
        element.style.fontFamily = layer.font ?? 'inherit'
        element.style.fontSize = `${layer.fontSize ?? 16}px`
        element.style.fontWeight = layer.fontWeight ?? '400'
        if (layer.lineHeight) element.style.lineHeight = layer.lineHeight
        if (layer.letterSpacing) element.style.letterSpacing = layer.letterSpacing
        if (layer.textAlign) element.style.textAlign = layer.textAlign
        element.style.color = layer.color ?? ink
        element.style.opacity = '0'
        element.style.clipPath = 'inset(0 100% 0 0)'
      }
      overlay?.appendChild(element)
      return element
    })

    cursorEls = Array.from({ length: cursorCount }, (_, index) => {
      const cursor = document.createElement('div')
      cursor.className = 'replay-cursor'
      cursor.style.setProperty('--cr-color', colors[index % colors.length])
      cursor.style.opacity = '0'
      overlay?.appendChild(cursor)
      return cursor
    })
    badgeEls = Array.from({ length: cursorCount }, () => {
      const badge = document.createElement('div')
      badge.className = 'replay-badge'
      overlay?.appendChild(badge)
      return badge
    })

    const rounds = Math.ceil(ordered.length / cursorCount)
    const per = clamp((duration - 800 - 600) / Math.max(1, rounds), 180, 900)
    introEnd = 700
    tasks = ordered.map((layer, index) => {
      const cursor = index % cursorCount
      const round = Math.floor(index / cursorCount)
      // Offset each cursor's lane so the page never pauses between rounds.
      const stagger = (cursor / cursorCount) * per * 0.7
      const start = introEnd + round * per + stagger
      return {
        layer,
        cursor,
        start,
        moveEnd: start + per * 0.7,
        actionStart: start + per * 0.22,
        actionEnd: start + per * 0.88,
      }
    })
    // Hold the finished frame briefly so the last box/text is readable before the fade.
    endAt = tasks.reduce((last, task) => Math.max(last, task.actionEnd), introEnd) + 900

    onKey = (event) => {
      if (event.key === 'Escape') cancel()
    }
    window.addEventListener('keydown', onKey, true)

    const cursorPosition = (cursor: number, time: number) => {
      const angle = (cursor / cursorCount) * Math.PI * 2
      const orbit = { x: center.x + Math.cos(angle) * 54, y: center.y + Math.sin(angle) * 40 }
      if (time < introEnd) {
        const p = clamp(time / introEnd, 0, 1)
        return {
          x: center.x + Math.cos(angle + p * Math.PI * 1.5) * (18 + p * 36),
          y: center.y + Math.sin(angle + p * Math.PI * 1.5) * (12 + p * 28),
        }
      }
      let position = orbit
      for (const task of tasks) {
        if (task.cursor !== cursor) continue
        if (time < task.start) break
        const target = task.layer
        const progress = easeInOutCubic(
          clamp((time - task.start) / Math.max(1, task.moveEnd - task.start), 0, 1),
        )
        position = { x: lerp(position.x, target.x, progress), y: lerp(position.y, target.y, progress) }
        if (time < task.moveEnd) break
      }
      return position
    }

    const activeTask = (cursor: number, time: number) => {
      let current: Task | null = null
      for (const task of tasks) {
        if (task.cursor !== cursor) continue
        if (time < task.actionStart) break
        if (time <= task.actionEnd) {
          current = task
          break
        }
      }
      return current
    }

    const started = performance.now()
    overlay.style.opacity = '0'
    options.onStart?.()
    playing = true

    const tick = (now: number) => {
      if (!overlay) return
      const time = clamp(now - started, 0, endAt)
      const fadeIn = clamp(time / 350, 0, 1)
      const fadeOut = 1 - clamp((time - (endAt - 600)) / 600, 0, 1)
      overlay.style.opacity = String(Math.min(fadeIn, fadeOut))

      tasks.forEach((task, index) => {
        const element = layerEls[index]
        const layer = task.layer
        const progress = clamp(
          (time - task.actionStart) / Math.max(1, task.actionEnd - task.actionStart),
          0,
          1,
        )
        if (time < task.actionStart) return
        const reveal = easeOutCubic(progress)
        if (layer.kind === 'text') {
          element.style.opacity = progress > 0 ? '1' : '0'
          element.style.clipPath = `inset(0 ${100 - reveal * 100}% 0 0)`
          element.style.transform = `translateY(${(1 - reveal) * 4}px)`
        } else if (layer.kind === 'image') {
          element.style.opacity = String(reveal)
          element.style.clipPath = `inset(0 0 ${100 - reveal * 100}% 0)`
        } else {
          element.style.clipPath = `inset(0 ${100 - reveal * 100}% ${100 - reveal * 100}% 0)`
          if (progress >= 1) element.style.outline = 'none'
        }
      })

      cursorEls.forEach((cursor, index) => {
        const position = cursorPosition(index, time)
        const active = activeTask(index, time)
        if (!active) {
          // A tiny idle drift keeps non-active cursors alive between lanes.
          const drift = Math.sin(time / 520 + index * 1.7) * 2.4
          position.x += Math.cos(time / 470 + index) * drift
          position.y += Math.sin(time / 610 + index * 1.3) * drift
        }
        const shape = active ? cursorShapeFor(active.layer) : time < introEnd ? 'arrow' : 'arrow'
        if (cursor.dataset.shape !== shape) {
          cursor.dataset.shape = shape
          cursor.innerHTML = cursorSvg(shape)
        }
        cursor.style.transform = `translate3d(${position.x}px, ${position.y}px, 0)`
        cursor.style.opacity = time < introEnd ? String(clamp(time / 180, 0, 1)) : '1'
        const badge = badgeEls[index]
        if (active && active.layer.kind !== 'text') {
          badge.textContent = `${Math.round(active.layer.width)} × ${Math.round(active.layer.height)}`
          badge.style.transform = `translate(${position.x + 18}px, ${position.y + 18}px)`
          badge.style.opacity = '1'
        } else {
          badge.style.opacity = '0'
        }
      })

      if (time >= endAt) {
        finish()
        return
      }
      frame = requestAnimationFrame(tick)
    }

    currentPlay = new Promise<void>((resolve) => {
      resolvePlay = resolve
      frame = requestAnimationFrame(tick)
    })
    return currentPlay
  }

  return {
    get playing() {
      return playing
    },
    play,
    cancel,
    destroy: () => {
      destroyed = true
      cancel()
      cleanup()
    },
  }
}

function prefersReducedMotion() {
  return (
    typeof window !== 'undefined' &&
    typeof window.matchMedia === 'function' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}
