export interface ReplayStep {
  index: number
  cursor: number
  moveStart: number
  moveEnd: number
  boxStart: number
  textStart: number
}

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export function buildSteps(count: number, duration: number, cursors: number): ReplayStep[] {
  const safeCount = Math.max(0, Math.floor(count))
  if (safeCount === 0) return []
  const total = clamp(duration, 600, 8000)
  const per = clamp(total / safeCount, 70, 260)
  const cursorCount = clamp(Math.floor(cursors), 1, 4)
  return Array.from({ length: safeCount }, (_, index) => {
    const start = index * per
    return {
      index,
      cursor: index % cursorCount,
      moveStart: start,
      moveEnd: start + per * 0.55,
      boxStart: start + per * 0.4,
      textStart: start + per * 0.65,
    }
  })
}

export const easeOutCubic = (value: number) => 1 - Math.pow(1 - clamp(value, 0, 1), 3)

export const easeInOutCubic = (value: number) => {
  const p = clamp(value, 0, 1)
  return p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2
}

export const lerp = (from: number, to: number, progress: number) =>
  from + (to - from) * progress
